mapper.insert:
insert into t_question (id, question_type, subject_id,
  score, user_group_id, difficult,
  correct, info_text_content_id, create_user,
  status, create_time, deleted, is_ai
  )
values (#{id,jdbcType=INTEGER}, #{questionType,jdbcType=INTEGER}, #{subjectId,jdbcType=INTEGER},
  #{score,jdbcType=INTEGER}, #{gradeLevel,jdbcType=INTEGER}, #{difficult,jdbcType=INTEGER},
  #{correct,jdbcType=VARCHAR}, #{infoTextContentId,jdbcType=INTEGER}, #{createUser,jdbcType=INTEGER},
  #{status,jdbcType=INTEGER}, #{createTime,jdbcType=TIMESTAMP}, #{deleted,jdbcType=BIT}, #{isAi,jdbcType=INTEGER}
  )

mapper.select:
SELECT

FROM t_question

    and deleted=0

    and id= #{id}


    and user_group_id= #{level}


    and subject_id= #{subjectId}


    and question_type= #{questionType}


    and info_text_content_id in (SELECT id FROM t_text_content WHERE content like concat('%',#{content},'%') )


    and create_user in (SELECT id FROM t_user WHERE role in (2, 3)) and (is_ai = 0 or is_ai is null)


    and (create_user in (SELECT id FROM t_user WHERE role = 1) or is_ai = 1)


    and exists (
      select 1
      from t_question_tag qt
      inner join t_tag tag on tag.id = qt.tag_id
      where qt.question_id = t_question.id
        and tag.name = #{practiceHiddenTagName}
    )


    and not exists (
      select 1
      from t_question_tag qt
      inner join t_tag tag on tag.id = qt.tag_id
      where qt.question_id = t_question.id
        and tag.name = #{practiceHiddenTagName}
    )


    and id in (
      select question_id
      from t_question_tag
      where tag_id in

        #{tagId}

      group by question_id
      having count(distinct tag_id) = ${tagIds.size()}
    )


    and id in (
      select distinct question_id
      from t_question_tag
      where tag_id in

        #{tagId}

    )

SELECT

FROM t_question

  and deleted=0

    and user_group_id = #{userGroupId}


    and subject_id = #{subjectId}


    and question_type = #{questionType}


    and not exists (
      select 1
      from t_question_tag hidden_qt
      inner join t_tag hidden_t on hidden_t.id = hidden_qt.tag_id and hidden_t.deleted = 0
      where hidden_qt.question_id = t_question.id
        and hidden_t.name = #{excludeTagName}
    )


    and id in (
      select question_id
      from t_question_tag
      where tag_id in

        #{tagId}

      group by question_id
      having count(distinct tag_id) = ${tagIds.size()}
    )


    and id in (
      select distinct question_id
      from t_question_tag
      where tag_id in

        #{tagId}

    )

SELECT

FROM t_question where id in

  #{id}

SELECT create_time as name,COUNT(create_time) as value from
        (
		  SELECT DATE_FORMAT(create_time,'%Y-%m-%d') as create_time from t_question
			WHERE  deleted=0  and  create_time  between  #{startTime}  and  #{endTime}
		) a
GROUP BY create_time
